sha=lambda b:hashlib.sha256(b).hexdigest()
def main():
 titles=json.loads((ROOT/'work/scratch/menus076-discovery/night-titles.json').read_text());assert len(EN)==len(titles)==181;assert max(map(len,EN))<=32
 night=dict(zip(titles,EN));gallery=json.loads((ROOT/'work/scratch/menus076-discovery/titles.json').read_text())['38'];cfg=json.loads((ROOT/'work/translation/en/menus_0.1.76/titles.json').read_text());english={e['row']:e['english'][0] for e in cfg['entries'] if e['table']==38};ending={e['text']:english[e['row']] for e in gallery if e['row'] in english}
 hidden_titles=json.loads((ROOT/'work/scratch/menus076-discovery/night-hidden-titles.json').read_text())
 hidden_en="A Hesitant First Step|The Right to Care|I Am Not Afraid...|I Am Happy!|To Stop Those Tears|An Endless Road|I Will Follow You...|Together, Always...|All My Courage|Another Home|My Favorite Teacher|A Surprise Attack|Beyond Master and Servant|Best Friends|Not Yet...|The Teacher's Senior???|A Promise to Meet Again|Glad We Met...|A Hint of Farewell|Live Looking Ahead|So You Can Be Yourself|A Cynic's Advice|Perhaps Love Begins...|For Someone Dear|Do as You Please|A Secret Informant|Her Resolve|Unexpected Good News?|An Angel in Love with Love|How a Love Ends|A New Student|A New Term Together!|The Oldest Memory|A Viper's Kindness|The Pain of Innocence|A Special Memory|Men and Guardians|Toward Our Goal|Honest Feelings|Sisters by Bond|Toward Unseen Seas|Signs of a Plot|Take Responsibility, Okay?|Who Are You?|Distance|A Wish from the Past|Feelings in Harmony|So Oblivious...".split('|')
 assert len(hidden_titles)==len(hidden_en)==48
 hidden=dict(zip(hidden_titles,hidden_en));out=[]
 with GameSource(ROOT/'work/output/0.1.75/Summon_Night_3_EN_0.1.75.iso') as s:
  for root,ch,mapping in [(3568,0,night),(3568,1,hidden),(3569,0,ending)]:
   b=descend(s.resource('02.DAT',root),[ch]);n,m=struct.unpack_from('<2I',b);count=n*m*2;groups={}
   for f in range(8,8+count*4,4):
    p=struct.unpack_from('<I',b,f)[0]
    if p:groups.setdefault(p,[]).append(f)
   if root==3569:
    unique=sorted({unicodedata.normalize('NFKC',lines_at(b,p)[0][0].decode('cp932')) for p in groups})
    translations='The Sun and the Snake|From Here to Eternity|Sighs and Smiles|Toward Unseen Seas|Keep on Smiling!|What We Inherit|At Eye Level|Eyes Full of Dreams|Embraced by Peace|I Am Happy|The Price of a Smile|Memories Become Strength|A New Teacher|Sunny Again Tomorrow!|Paradise Close at Hand|A Mechanical New Student|Go with the Flow|Unbeatable Smile|With Honest Feelings|Wishing You Happiness|By Your Side'.split('|')
    assert len(unique)==len(translations)==21;mapping=dict(zip(unique,translations))
   for p,fields in groups.items():
    raw=lines_at(b,p)[0][0];text=unicodedata.normalize('NFKC',raw.decode('cp932'));en=mapping[text]
    out.append(dict(path=[root,ch],source_offset=p,source_sha256=sha(raw),pointer_fields=fields,english=[en]))
 (ROOT/'work/translation/en/menus_0.1.76/gallery_captions.json').write_text(json.dumps(dict(entries=out,night_talk_titles=229,ending_titles=21),indent=2)+'\n');print(len(out))
if __name__=='__main__':main()
